import React from "react";
import {
  Box,
  Flex,
  Text,
  Progress,
  Tag,
  Stat,
  StatLabel,
  StatNumber,
  StatGroup,
} from "@chakra-ui/react";

import Card from "components/card/Card";

const AnalysisCard = ({ data, ...rest }) => {

  const impersonationResults =[
    { word: "microsof.com", distance: 3 },
    { word: "microsoft.com", distance: 3 },
  ];

  if (!data) {
    return (
      <Card
        p="20px"
        align="center"
        w="100%"
        {...rest}
        h="auto"
        boxShadow="lg"
      >
        <Text fontSize="xl" fontWeight="bold" color="gray.400">
          No data available
        </Text>
      </Card>
    );
  }
  



    const {url, severityScore, severity, category, stats = {} } = data;
    
    const severityColors = {
      Low: "green.300",
      Medium: "yellow.300",
      High: "red.300",
      Critical: "red.600",
    };

    return (
      <>
        {/* Main Analysis Card */}
        <Card p="20px" align="center" w="100%" {...rest} h="auto" boxShadow="lg">
          {/* URL */}
          <Text fontSize="xl" fontWeight="bold" isTruncated>
            {url}
          </Text>
  
          {/* Severity and Category */}
          <Flex mt={2} align="center" justify="space-between">
            <Tag colorScheme="teal" size="md">
              {category}
            </Tag>
            <Tag
              size="md"
              bg={severityColors[severity] || "gray.500"}
              color="white"
            >
              {severity}
            </Tag>
          </Flex>
  
          {/* Severity Score Progress */}
          <Text mt={4} fontSize="sm" color="gray.400">
            Severity Score
          </Text>
          <Progress
            value={severityScore}
            max={10}
            colorScheme="red"
            size="sm"
            borderRadius="md"
            mt={2}
          />
          <Text fontSize="sm" color="gray.300">
            {severityScore} / 10
          </Text>
  
          {/* Stats */}
          <StatGroup mt={4}>
            <Stat>
              <StatLabel>Harmless</StatLabel>
              <StatNumber>{stats.harmless}</StatNumber>
            </Stat>
            <Stat>
              <StatLabel>Malicious</StatLabel>
              <StatNumber>{stats.malicious}</StatNumber>
            </Stat>
            <Stat>
              <StatLabel>Suspicious</StatLabel>
              <StatNumber>{stats.suspicious}</StatNumber>
            </Stat>
            <Stat>
              <StatLabel>Undetected</StatLabel>
              <StatNumber>{stats.undetected}</StatNumber>
            </Stat>
            <Stat>
              <StatLabel>Timeout</StatLabel>
              <StatNumber>{stats.timeout}</StatNumber>
            </Stat>
          </StatGroup>
        </Card>
  
        {impersonationResults?.length > 0 && (
          <Box mt={8} p={4} borderRadius="md" bg="gray.700" color="white">
            <Text fontSize="lg" fontWeight="bold" mb={4}>
              Impersonation Detection
            </Text>
  
            <Text fontSize="md" mb={2}>
              The domain <b>www.m!cros0fl.com</b> appears to be an impersonator. Below are the domains it might be impersonating:
            </Text>
  
            <Box mt={4} pl={4}>
              {impersonationResults.map((result, index) => (
                <Flex
                  key={index}
                  align="center"
                  justify="space-between"
                  p={2}
                  borderBottom="1px solid"
                  borderColor="gray.600"
                >
                  <Text fontSize="md" color="blue.300">
                    {result.word}
                  </Text>

                  <Tag size="md" colorScheme="teal">
                    Distance: {result.distance}
                  </Tag>
                </Flex>
              ))}
            </Box>
          </Box>
        )}
      </>
    );
  };


export default AnalysisCard;